import React, { useEffect, useState } from 'react';

function MisApps() {
  const [apps, setApps] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [message, setMessage] = useState('');

  useEffect(() => {
    const fetchApps = async () => {
      setLoading(true);
      setError('');
      setMessage('');
      const token = localStorage.getItem('token');
      if (!token) {
        setError('No autenticado. Inicia sesión.');
        setLoading(false);
        return;
      }
      try {
        const response = await fetch('http://localhost:8000/api/apps', {
          headers: { 'Authorization': `Bearer ${token}` }
        });
        if (!response.ok) {
          setError('No se pudieron cargar las aplicaciones.');
          setLoading(false);
          return;
        }
        const data = await response.json();
        setApps(data);
      } catch (err) {
        setError('Error de conexión con el servidor.');
      }
      setLoading(false);
    };
    fetchApps();
  }, []);

  const handleRunApp = async (appId) => {
    setMessage('');
    setError('');
    const token = localStorage.getItem('token');
    try {
      const response = await fetch(`http://localhost:8000/api/apps/${appId}/run`, {
        method: 'POST',
        headers: { 'Authorization': `Bearer ${token}` }
      });
      if (!response.ok) {
        const data = await response.json();
        setError(data.detail || 'No se pudo ejecutar la aplicación.');
        return;
      }
      const data = await response.json();
      setMessage(data.message || 'Aplicación ejecutada correctamente.');
    } catch (err) {
      setError('Error de conexión al ejecutar la aplicación.');
    }
  };

  return (
    <div className="container py-5">
      <div className="row justify-content-center">
        <div className="col-md-10">
          <h2 className="mb-4">Mis Aplicaciones</h2>
          {loading && <div className="alert alert-info">Cargando aplicaciones...</div>}
          {error && <div className="alert alert-danger">{error}</div>}
          {message && <div className="alert alert-success">{message}</div>}
          {!loading && !error && (
            apps.length > 0 ? (
              <div className="row">
                {apps.map(app => (
                  <div className="col-md-6 col-lg-4 mb-4" key={app.id}>
                    <div className="card h-100">
                      <div className="card-body">
                        <h5 className="card-title">{app.name}</h5>
                        <p className="card-text">{app.description}</p>
                        <span className="badge bg-secondary">{app.category}</span>
                      </div>
                      <div className="card-footer text-end">
                        <button className="btn btn-primary" onClick={() => handleRunApp(app.id)}>
                          Ejecutar
                        </button>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            ) : (
              <div className="alert alert-info">No tienes aplicaciones asignadas.</div>
            )
          )}
        </div>
      </div>
    </div>
  );
}

export default MisApps;
